 private const string Owner="fixture:wangcan",Driver="fixture:wangcan-driver",Quiet="fixture:wangcan-quiet",Watch="fixture:wangcan-watch",Mode="identity:classic-wangcan-fixture";
 public static void ActualSanwenPriorWitnessBatchAndTurnQuotaCold()
 {
  var(g,r)=Start();Play(g);Use(g,"clear-draw");Play(g);Need(!E<WangCanStartedEvent>(g).Any(e=>e.Operation==SkillProgramEffectOp.ResolveSanwenActualGainDuplicates),"Two equal incoming cards do not witness each other after the original hand was actually discarded.");Use(g,"draw");Offer(g,"ol:sanwen");var window=g.ResolutionStack.OfType<CardsMovedTriggerWindowFrame>().Last();var proof=window.Batch.SanwenGains!.Single(q=>q.OwnerSeat==0);Need(proof.Incoming.Count==2&&proof.Witnesses.Count==2&&proof.Incoming.All(i=>proof.Witnesses.All(w=>w.CardId!=i.CardId)),"The actual incoming batch freezes distinct prior-hand witnesses.");g=Cold(g,r);Activate(g);Play(g);g=Cold(g,r);var paid=E<WangCanSegmentPaidEvent>(g).Where(e=>e.Source.SkillId=="ol:sanwen").ToArray();Need(paid.Single(e=>e.Stage==WangCanStage.SanwenDiscard).ActualCount==2&&paid.Single(e=>e.Stage==WangCanStage.SanwenDraw).ActualCount==4&&V(g,0).Hand.Count==6,"Two actual incoming discards produce exactly four native draws, preserving the original two witnesses.");Need(E<ProgramCardsRevealedEvent>(g).Single(e=>e.SkillId=="ol:sanwen").Cards.Select(c=>c.Id).Order().SequenceEqual(proof.Witnesses.Select(w=>w.CardId).Order()),"Only the actual old matching hand witnesses are deliberately revealed.");Use(g,"draw");Play(g);Need(E<WangCanStartedEvent>(g).Count(e=>e.Operation==SkillProgramEffectOp.ResolveSanwenActualGainDuplicates)==1,"The real-turn quota is consumed before the skill's own native draw can re-enter it.");_=Cold(g,r);
 }
 private static PlayerSnapshot V(GameEngine g,int seat)=>g.CreateSnapshot(seat).Players[seat];
 private static PendingDecision? P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p is not null);
 private static IEnumerable<T>E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>();
 private static void Need(bool value,string message){if(!value)throw new InvalidOperationException(message);}
 private static void Accept(GameEngine g,GameCommand command){var result=g.Submit(CommandJson.Deserialize(CommandJson.Serialize([command])).Single());Need(result.Accepted,result.Error?.Message??"Rejected actual Wang Can command.");}
 private static void Answer(GameEngine g,Func<PromptChoice,bool> predicate){var p=P(g)!;Accept(g,new AnswerPromptCommand(p.PlayerSeat,p.PromptId,p.Choices.First(predicate).Id,g.Revision));}
 private static void Use(GameEngine g,string id)=>Accept(g,new UseProgramSkillCommand(0,Driver,id,[],[],g.Revision,P(g)!.PromptId));
 private static void Offer(GameEngine g,string skill)=>Reach(g,()=>P(g)?.SkillPrompt?.SkillId==skill&&P(g)!.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="activate"));
 private static void Activate(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate");
 private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
 private static void Reach(GameEngine g,Func<bool> done){for(var i=0;i<180;i++){if(done())return;var p=P(g);if(p?.PlayerSeat==0&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip"))Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");else if(p is{PlayerSeat:0,Kind:DecisionKind.RescueDying or DecisionKind.RespondDodge or DecisionKind.RespondSlash}&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("response")is"let-die"or"pass"or"take-damage"))Answer(g,c=>c.Parameters.GetValueOrDefault("response")is"let-die"or"pass"or"take-damage");else Accept(g,new AdvanceOneStepCommand(g.Revision));}throw new InvalidOperationException("Wang Can boundary missing "+JsonSerializer.Serialize(new{Prompt=P(g)?.Kind,Skill=P(g)?.SkillPrompt?.SkillId,Frames=g.ResolutionStack.Select(f=>new{f.Id,f.Kind}),Recent=g.Events.TakeLast(8).Select(e=>e.Payload.GetType().Name)}));}
 private static string State(GameEngine g)=>JsonSerializer.Serialize(new{Views=Enumerable.Range(0,4).Select(s=>SnapshotJson.Serialize(g.CreateSnapshot(s))),Frames=g.ResolutionStack.Select(f=>JsonSerializer.Serialize(f,f.GetType())),Events=g.Events.Select(e=>JsonSerializer.Serialize(e.Payload,e.Payload.GetType())),g.CardMovements});
 private static GameEngine Cold(GameEngine g,ContentRegistry r){var cold=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(g.CreateCheckpoint())),r);Need(State(g)==State(cold),"All private views, true gain witnesses, limited payer cursors and exact leased native entities survive command-prefix cold recovery.");return cold;}
 private static string Read(string suffix){using var stream=typeof(StandardClassicGeneralPackage).Assembly.GetManifestResourceStream("CardGame.Content.Standard.SkillPrograms.ol-wang-can."+suffix)!;using var reader=new StreamReader(stream);return reader.ReadToEnd();}
 private static(GameEngine,ContentRegistry)Start(string scenario="sanwen")
 {var r=ContentRegistry.Build(new StandardContentPackage(),new Fixture(scenario));var g=GameEngine.CreateStandard(new GameOptions{Seed=7,PlayerCount=4,HumanSeat=0,HumanRole=scenario is"qiai"or"death"?Role.Rebel:Role.Lord,ModeId=Mode,UseInteractiveSetup=true,AdvanceAfterHumanCommands=false,UseInteractiveDiscard=false,MaxTurns=8},r);Accept(g,new StartGameCommand());Reach(g,()=>P(g)is{Kind:DecisionKind.SelectGeneral,PlayerSeat:0});Accept(g,new SelectGeneralCommand(0,scenario=="qiai-human"?"fixture:wangcan-human":Owner,g.Revision,P(g)!.PromptId));return(g,r);}
